import java.util.*;import java.nio.file.*;import com.alibaba.fastjson2.*;import webridge.wbridge.sql.result.MultipleRowResultSetImpl;
public class NumericResultAudit {public static void main(String[] args)throws Exception{JSONObject out=new JSONObject();List<List<Object>> rows=Arrays.asList(Arrays.<Object>asList("node","edge",1348704000000L,"title"));MultipleRowResultSetImpl r=new MultipleRowResultSetImpl(Arrays.asList("n","e","forum_id","title"),Collections.nCopies(4,""),rows);r.next();try{r.getString(3);throw new AssertionError("Expected original strict cast failure");}catch(ClassCastException expected){out.put("numeric_getString_failure",expected.toString());}long value=r.getLong(3);if(value!=1348704000000L||r.wasNull())throw new AssertionError();out.put("numeric_getLong_pass",value);MultipleRowResultSetImpl n=new MultipleRowResultSetImpl(Arrays.asList("v"),Arrays.asList(""),Arrays.asList(Arrays.<Object>asList((Object)null)));n.next();if(n.getLong(1)!=0||!n.wasNull())throw new AssertionError();out.put("numeric_null_getLong_wasNull_pass",true);Files.write(Paths.get(args[0]),out.toJSONString().getBytes("UTF-8"));System.out.println(out);}}
